  function bindDocumentEvidence(){const transmittal=document.getElementById('documentTransmittalForm'),candidate=document.getElementById('drawingIntelligenceForm');if(transmittal&&!transmittal.dataset.bound){transmittal.dataset.bound='1';transmittal.addEventListener('submit',createDocumentTransmittal);transmittal.elements.purpose.addEventListener('change',renderDocumentEvidence);}if(candidate&&!candidate.dataset.bound){candidate.dataset.bound='1';candidate.addEventListener('submit',createDrawingIntelligenceCandidate);candidate.elements.revisionId.addEventListener('change',prefillDrawingIntelligenceCandidate);}}
  function prefillDrawingIntelligenceCandidate(){const form=document.getElementById('drawingIntelligenceForm'),item=documentRevisions.find(revision=>revision.id===form.elements.revisionId.value);if(!item?.drawing)return;form.elements.detectedDiscipline.value=item.discipline;form.elements.drawingNumber.value=item.drawing.drawingNumber;form.elements.title.value=item.title;form.elements.scale.value=item.drawing.scale||'not recorded';form.elements.date.value=new Date().toISOString().slice(0,10);form.elements.revision.value=item.revisionCode;form.elements.issuePurpose.value=item.issuePurpose;}
  async function createDocumentTransmittal(event){event.preventDefault();const form=event.currentTarget,v=new FormData(form),message=document.getElementById('documentTransmittalMessage'),revisionIds=v.getAll('revisionIds'),recipientRoles=String(v.get('recipientRoles')).split(',').map(x=>x.trim().toLowerCase().replaceAll(' ','_')).filter(Boolean);message.textContent='Creating draft transmittal…';try{await api.post('/document-transmittals',{projectId:window.__ARCHITEX_SHELL_STATE__.selectedProjectId,code:v.get('code'),title:v.get('title'),purpose:v.get('purpose'),recipientRoles,revisionIds,notes:v.get('notes')});message.textContent='Draft transmittal recorded; formal issue remains a separate confirmation.';await hydrateDocumentControl();}catch(error){message.textContent=error.message;}}
  window.issueDocumentTransmittal=async function(id){const reason=prompt('Why should this exact revision set be issued?','I checked the exact revisions, purpose and recipient roles.');if(!reason?.trim()||!confirm('Issue and lock this exact transmittal snapshot? External delivery is not claimed.'))return;try{await api.post(`/document-transmittals/${encodeURIComponent(id)}/issue`,{humanConfirmed:true,reason:reason.trim()});showToast('Transmittal snapshot issued to internal role inboxes. External delivery is not claimed.');await hydrateDocumentControl();}catch(error){showToast(error.message);}};
  async function createDrawingIntelligenceCandidate(event){event.preventDefault();const form=event.currentTarget,v=new FormData(form),message=document.getElementById('drawingIntelligenceMessage');message.textContent='Recording human-entered candidate…';try{await api.post('/drawing-intelligence-candidates',{revisionId:v.get('revisionId'),provenance:'human_entered',providerName:null,providerReference:null,confidence:null,candidate:{classification:v.get('classification'),detectedDiscipline:v.get('detectedDiscipline'),titleBlock:{drawingNumber:v.get('drawingNumber'),title:v.get('title'),scale:v.get('scale'),date:v.get('date'),author:v.get('author')},revision:v.get('revision'),issuePurpose:v.get('issuePurpose'),findings:[v.get('findings')],suggestedNextAction:v.get('suggestedNextAction')}});message.textContent='Human-entered candidate saved. No controlled metadata was applied.';await hydrateDocumentControl();}catch(error){message.textContent=error.message;}}
  async function reviewDrawingIntelligenceCandidate(id,decision){const reason=prompt(`Why is this candidate ${decision}?`,'Compared every proposed field with the exact controlled source drawing.');if(!reason?.trim()||!confirm(`${decision==='accepted'?'Accept':'Reject'} this exact candidate? Controlled metadata will remain unchanged.`))return;try{const reviewed=await api.post(`/drawing-intelligence-candidates/${encodeURIComponent(id)}/review`,{decision,humanConfirmed:true,reason:reason.trim()});showToast(`Candidate ${reviewed.status}; metadata applied: ${reviewed.metadataApplied?'yes':'no'}.`);await hydrateDocumentControl();}catch(error){showToast(error.message);}}
