  window.rejectDrawingIntelligenceCandidate=id=>reviewDrawingIntelligenceCandidate(id,'rejected');
  async function createControlledDocument(event){event.preventDefault();const form=event.currentTarget,v=new FormData(form),message=document.getElementById('documentCreateMessage'),type=v.get('documentType'),body={projectId:window.__ARCHITEX_SHELL_STATE__.selectedProjectId,title:v.get('title'),documentType:type,discipline:v.get('discipline'),phase:v.get('phase'),issuePurpose:v.get('issuePurpose'),revisionCode:v.get('revisionCode'),notes:v.get('notes')};if(type==='drawing')body.drawing={drawingNumber:v.get('drawingNumber'),sheetType:v.get('sheetType'),scale:v.get('scale')};message.textContent='Creating controlled draft…';try{const created=await api.post('/documents',body);activeDocumentRevisionId=created.id;form.reset();message.textContent='Controlled draft created and audited.';await hydrateDocumentControl();}catch(error){message.textContent=error.message;}}
  async function saveControlledDocumentDraft(event){event.preventDefault();const form=event.currentTarget,item=documentRevisions.find(x=>x.id===activeDocumentRevisionId),v=new FormData(form),message=document.getElementById('documentRevisionMessage'),body={notes:v.get('notes')};if(item.drawing)body.drawing={drawingNumber:v.get('drawingNumber'),sheetType:v.get('sheetType'),scale:v.get('scale')};try{await api.post(`/documents/${encodeURIComponent(item.id)}/draft`,body);message.textContent='Draft metadata saved and audited.';await hydrateDocumentControl();}catch(error){message.textContent=error.message;}}
  window.submitDocumentReview=async function(){const reason=prompt('Reason for professional review?','Drawing metadata and linked evidence are ready for professional review.');if(!reason?.trim())return;try{await api.post(`/documents/${encodeURIComponent(activeDocumentRevisionId)}/submit-review`,{reason:reason.trim()});await hydrateDocumentControl();}catch(error){showToast(error.message);}};
  window.approveControlledDocument=async function(){const reason=prompt('Why is this exact revision approved?','I personally reviewed the exact revision metadata and linked evidence.');if(!reason?.trim()||!confirm('Approve this exact controlled revision?'))return;try{await api.post(`/documents/${encodeURIComponent(activeDocumentRevisionId)}/approve`,{humanConfirmed:true,reason:reason.trim()});await hydrateDocumentControl();}catch(error){showToast(error.message);}};
  window.issueControlledDocument=async function(){const form=document.getElementById('documentRevisionForm'),purpose=new FormData(form).get('issuePurpose'),reason=prompt('Reason for formal issue?','Responsible professional approved this exact revision for its recorded purpose.');if(!reason?.trim()||!confirm('Issue and lock this exact controlled revision?'))return;try{await api.post(`/documents/${encodeURIComponent(activeDocumentRevisionId)}/issue`,{humanConfirmed:true,reason:reason.trim(),issuePurpose:purpose});await hydrateDocumentControl();}catch(error){showToast(error.message);}};
  window.reviseControlledDocument=async function(){const form=document.getElementById('documentRevisionForm'),item=documentRevisions.find(x=>x.id===activeDocumentRevisionId),v=new FormData(form),reason=v.get('revisionReason');if(!reason?.trim()||!confirm('Supersede this issued revision and create a linked draft?'))return;const body={revisionCode:v.get('revisionCode'),reason,notes:v.get('notes'),issuePurpose:'for_review'};if(item.drawing)body.drawing={drawingNumber:v.get('drawingNumber'),sheetType:v.get('sheetType'),scale:v.get('scale')};try{const revision=await api.post(`/documents/${encodeURIComponent(item.id)}/revisions`,body);activeDocumentRevisionId=revision.id;await hydrateDocumentControl();showToast('Linked revision created; the prior issue remains visible as superseded.');}catch(error){showToast(error.message);}};
