  function applyPendingCommunicationContext(){if(!pendingCommunicationContext)return;const form=document.getElementById('communicationComposer');if(!form)return;for(const[name,value]of Object.entries({sourceObjectType:pendingCommunicationContext.sourceObjectType,sourceObjectId:pendingCommunicationContext.sourceObjectId,contextTitle:pendingCommunicationContext.title,persistencePolicy:pendingCommunicationContext.persistencePolicy}))if(value&&form.elements[name])form.elements[name].value=value;if(pendingCommunicationContext.body)form.elements.body.value=pendingCommunicationContext.body;form.querySelector('details').open=true;}

  async function hydrateFeeWorkspace(){const schedule=document.getElementById('feeScheduleForm'),calculator=document.getElementById('feeCalculatorForm'),proposal=document.getElementById('proposalBuilderForm'),appointment=document.getElementById('appointmentCreateForm');if(!schedule||!calculator||!proposal||!appointment)return;try{const[definitions,runs,proposals,appointments]=await Promise.all([api.get('/fee-definitions'),api.get('/toolbox/runs?limit=20'),api.get('/proposals'),api.get('/appointments')]);const verified=definitions.filter(item=>item.status==='verified'&&item.sourceStatus==='verified');calculator.elements.definitionId.innerHTML='<option value="">Select a verified schedule</option>'+verified.map(item=>`<option value="${escapeHtml(item.id)}">${escapeHtml(item.name)} · ${escapeHtml(item.profession.replaceAll('_',' '))} · v${escapeHtml(item.version)}</option>`).join('');if(!verified.length)calculator.elements.definitionId.innerHTML='<option value="">Create and verify a practice schedule first</option>';const projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId,issued=runs.filter(run=>run.toolId==='professional_fee_calculator'&&run.status==='issued'&&run.assignment.projectId===projectId),projectProposals=proposals.filter(item=>item.projectId===projectId),projectAppointments=appointments.filter(item=>item.projectId===projectId),usedProposalIds=new Set(projectAppointments.map(item=>item.proposalId)),accepted=projectProposals.filter(item=>item.status==='accepted'&&!usedProposalIds.has(item.id));proposal.elements.feeRunId.innerHTML='<option value="">Select an issued project fee</option>'+issued.map(run=>`<option value="${escapeHtml(run.id)}">${money(run.output.totalInclVat)} · ${escapeHtml(run.createdAt)}</option>`).join('');appointment.dataset.latestId=projectAppointments[0]?.id||'';appointment.elements.proposalId.innerHTML=`<option value="">${projectAppointments.length?'Select a newly accepted proposal revision':'Select an accepted proposal'}</option>`+accepted.map(item=>`<option value="${escapeHtml(item.id)}">${escapeHtml(item.title)} · v${item.version}</option>`).join('');const project=window.__ARCHITEX_SHELL_STATE__?.projects.find(item=>item.id===projectId);if(project&&!proposal.elements.clientName.value)proposal.elements.clientName.value=project.clientName||'';if(project&&!appointment.elements.municipality.value)appointment.elements.municipality.value=project.municipality||'';if(project&&!appointment.elements.propertyDescription.value)appointment.elements.propertyDescription.value=project.propertyReference||'';renderFeeHistory(runs);renderProposalHistory(projectProposals);renderAppointmentHistory(projectAppointments);if(!schedule.dataset.bound){schedule.dataset.bound='1';schedule.addEventListener('submit',createFeeSchedule);calculator.addEventListener('submit',runFeeCalculator);proposal.addEventListener('submit',createProposal);appointment.addEventListener('submit',createAppointment);}}catch(error){document.getElementById('feeRunHistory').innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}const date=schedule.elements.effectiveDate;if(!date.value)date.value=new Date().toISOString().slice(0,10);}
  async function createFeeSchedule(event){event.preventDefault();const form=event.currentTarget,v=new FormData(form),message=document.getElementById('feeScheduleMessage'),verification={verificationReason:'Human-reviewed internal practice schedule and formula.'};message.textContent='Creating draft source…';try{const source=await api.post('/fee-sources',{profession:v.get('profession'),body:'Practice-approved schedule',title:v.get('title'),effectiveDate:v.get('effectiveDate'),sourceUrl:null,metadata:{basis:'Internal practice estimating schedule; not a statutory tariff.'}});await api.post(`/fee-sources/${encodeURIComponent(source.id)}/verify`,verification);const definition=await api.post('/fee-definitions',{profession:v.get('profession'),name:v.get('title'),version:v.get('version'),formulaType:'percentage_of_cost',sourceVersionId:source.id,configuration:{percentage:Number(v.get('percentage'))/100,vatRate:Number(v.get('vatRate'))/100,complexities:{normal:1},categories:{standard:1},stages:[{id:'all',name:'All selected professional services',weight:1}]}});await api.post(`/fee-definitions/${encodeURIComponent(definition.id)}/verify`,verification);message.textContent='Schedule source and formula verified with audit records.';await hydrateFeeWorkspace();}catch(error){message.textContent=error.message;}}
  async function runFeeCalculator(event){event.preventDefault();const form=event.currentTarget,v=new FormData(form),message=document.getElementById('feeCalculatorMessage');message.textContent='Calculating…';try{const definition=(await api.get('/fee-definitions')).find(item=>item.id===v.get('definitionId'));if(!definition)throw new Error('Select a verified fee schedule.');const discount=Number(v.get('discount'))/100,mode=v.get('assignment'),projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;let assignment={mode};if(mode==='internal_project'){if(!projectId)throw new Error('Select an Architex project first.');assignment={mode,projectId};}if(mode==='external_reference')assignment={mode,externalReference:v.get('externalReference')};const input={definitionId:definition.id,projectValue:Number(v.get('projectValue')),complexityId:'normal',categorySplits:{standard:1},selectedStages:{all:{applicable:true,reduction:0}},hourlyLines:[],unitLines:[],disbursements:Number(v.get('disbursements'))?[{label:'Disbursements',amount:Number(v.get('disbursements'))}]:[],statutoryFees:Number(v.get('statutoryFees'))?[{label:'Statutory fees',amount:Number(v.get('statutoryFees'))}]:[],discount:{percentage:discount,reason:String(v.get('discountReason')||'')},vatApplicable:v.get('vatApplicable')==='on'};const run=await api.post('/toolbox/runs',{toolId:'professional_fee_calculator',input,assignment,issueImmediately:v.get('issueImmediately')==='on',issueReason:v.get('issueReason')});document.getElementById('feeResult').innerHTML=`<div class="notice fee-result"><b>Total incl. VAT: ${money(run.output.totalInclVat)}</b><br>Guideline / calculated fee: ${money(run.output.guidelineProfessionalFee)} · after discount: ${money(run.output.professionalFeeAfterDiscount)} · statutory fees: ${money(run.output.statutoryFeesTotal)}<br><small>${escapeHtml(run.output.limitations)}${run.auditHash?' · SHA-256 '+escapeHtml(run.auditHash):''}</small></div>`;message.textContent=run.status==='issued'?'Issued and locked.':'Calculation saved.';await hydrateFeeWorkspace();}catch(error){message.textContent=error.message;}}
  function money(value){return new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR'}).format(Number(value)||0)}
