  window.refreshFeeWorkspace=hydrateFeeWorkspace;window.loadFeeExports=async function(runId){try{const exports=await api.get(`/toolbox/runs/${encodeURIComponent(runId)}/exports`);const list=document.getElementById('feeRunHistory');list.insertAdjacentHTML('afterbegin',`<div class="fee-export-row">${exports.map(file=>`<button class="btn ghost" type="button" onclick="downloadFeeExport('${escapeHtml(file.id)}')">Download ${escapeHtml(file.format.toUpperCase())}</button>`).join('')}</div>`);}catch(error){showToast(error.message);}};
  window.downloadFeeExport=async function(exportId){try{const response=await fetch(`${api.base}/toolbox/exports/${encodeURIComponent(exportId)}`,{headers:{Accept:'application/octet-stream','X-Organisation-Id':api.organisationId},credentials:'same-origin'});if(!response.ok){const payload=await response.json().catch(()=>null);throw new Error(payload?.error?.message||'Export download failed.');}const blob=await response.blob(),disposition=response.headers.get('Content-Disposition')||'',match=disposition.match(/filename="([^"]+)"/),link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download=match?.[1]||`architex-evidence-${exportId}`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('Evidence export downloaded.');}catch(error){showToast(error.message);}};
